// Convert Apollo data to CSV format with all required columns
const items = $input.all();
const csvRows = ['First Name,Last Name,Email,Company,Phone,Added']; // Header row

items.forEach(item => {
  if (item.json.email) {
    const row = [
      item.json.first_name || '',
      item.json.last_name || '',
      item.json.email || '',
      item.json.employment_history?.[0]?.organization_name || item.json.organization?.name || '',
      item.json.phone || '',
      new Date().toLocaleDateString('en-US', { 
        year: 'numeric', 
        month: 'short', 
        day: 'numeric' 
      })
    ];

    // Escape fields that contain commas or quotes
    const escapedRow = row.map(field => {
      const str = String(field);
      if (str.includes(',') || str.includes('"')) {
        return `"${str.replace(/"/g, '""')}"`;
      }
      return str;
    });

    csvRows.push(escapedRow.join(','));
  }
});

const csvContent = csvRows.join('\n');

// Build filename with timestamp instead of random number
const timestamp = new Date().toISOString().slice(0, 19).replace(/[-:]/g, '').replace('T', '_');
const fileName = `leads_to_verify_${timestamp}.csv`;

return {
  json: {
    status: 'csv_created',
    fileName
  },
  binary: {
    data: {
      data: Buffer.from(csvContent, 'utf8').toString('base64'),
      mimeType: 'text/csv',
      fileName
    }
  }
};

// CSV string is coming in as $json.data
const csvContent = $json.data;

if (!csvContent) {
  throw new Error("No CSV data found in 'data' field.");
}

// Step 1: Split into lines
const rows = csvContent.split(/\r?\n/).filter(r => r.trim() !== '');
const header = rows[0].split(',').map(h => h.trim());

// Step 2: Parse each row into JSON
const items = rows.slice(1).map(row => {
  const values = [];
  let inQuotes = false;
  let current = '';

  for (let i = 0; i < row.length; i++) {
    const char = row[i];
    if (char === '"' && row[i + 1] === '"') {
      current += '"'; // escaped quote
      i++;
    } else if (char === '"') {
      inQuotes = !inQuotes;
    } else if (char === ',' && !inQuotes) {
      values.push(current);
      current = '';
    } else {
      current += char;
    }
  }
  values.push(current);

  const obj = {};
  header.forEach((h, i) => {
    obj[h] = values[i] !== undefined ? values[i].trim() : '';
  });

  return { json: obj };
});

return items;
